 function burst(x,y,color,n){for(let i=0;i<n;i++){let a=rand(0,Math.PI*2),s=rand(30,190);particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:rand(.2,.6),max:.6,color,r:rand(1,3)})}}
 function shoot(e){let dx=player.x-e.x,dy=player.y-e.y,d=Math.hypot(dx,dy),speed=190;bolts.push({x:e.x,y:e.y,vx:dx/d*speed,vy:dy/d*speed,r:3,life:2,force:false});}
 function update(dt){if(state!=='play')return;player.invuln=Math.max(0,player.invuln-dt);saberTime=Math.max(0,saberTime-dt);forceFlash=Math.max(0,forceFlash-dt);player.force=Math.min(100,player.force+dt*5);
 let mx=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0),my=(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0);if(mx||my){let l=Math.hypot(mx,my);mx/=l;my/=l;player.x+=mx*220*dt;player.y+=my*220*dt;player.facing=Math.atan2(my,mx);}player.x=clamp(player.x,48,W-48);player.y=clamp(player.y,H*.29,H-85);
